std::u32string duration(std::uint64_t ms){const auto minutes=ms/60000;return unicodeText(minutes>=60?std::to_string(minutes/60)+" 小时 "+std::to_string(minutes%60)+" 分钟":std::to_string(minutes)+" 分钟");}
class UsageDialog final:public PixelDialog {
 const PixelFont& font_;const Skin& skin_;usage::Summary summary_;std::function<void()> export_,reset_;PixelButton *close_,*done_,*exportButton_,*resetButton_;std::u32string error_;bool confirm_=false;int activeDaily_=29,activeWeekly_=11;
 void chart(ui::Graphics& g,const std::vector<usage::Period>& periods,int y,int width,bool weekly){
  const int active=std::clamp(weekly?activeWeekly_:activeDaily_,0,int(periods.size())-1);font_.draw(g,weekly?U"最近 12 周":U"最近 30 天",8,y,skin_["text"]);if(periods.empty())return;const auto& item=periods[active];font_.draw(g,unicodeText(item.key)+U"  "+duration(item.usageMs),140,y,skin_["muted"]);std::uint64_t maximum=3600000;for(const auto& p:periods)maximum=std::max(maximum,p.usageMs);const auto quantum=maximum<=3600000?60000ULL:3600000ULL;maximum=((maximum+quantum-1)/quantum)*quantum;const int step=std::max(1,(width-16)/int(periods.size()));bool any=false;for(int i=0;i<int(periods.size());++i){const auto value=periods[i].usageMs;if(value){any=true;const int h=std::max(2,int(38.0*value/maximum));g.fillRect(skin_[i==active?"text":"muted"],{8+i*step,y+52-h,std::max(1,step-2),h});}}if(!any)font_.draw(g,U"暂无使用记录",8,y+24,skin_["muted"]);font_.draw(g,unicodeText(periods.front().key),8,y+55,skin_["muted"]);const auto last=unicodeText(periods.back().key);font_.draw(g,last,width-8-font_.measure(last),y+55,skin_["muted"]);
 }
public:
 UsageDialog(const PixelFont& f,const Skin& s,const Skin& icons,usage::Summary summary,std::function<void()> ex,std::function<void()> reset):PixelDialog(s,"",ui::PopupWindow::ClickBehavior::CloseOnClickInOtherWindow),font_(f),skin_(s),summary_(std::move(summary)),export_(std::move(ex)),reset_(std::move(reset)){
  setAutoRemap(false);setWantFocus(true);setEnterBehavior(ui::PopupWindow::EnterBehavior::DoNothingOnEnter);auto button=[&](std::u32string title,std::function<void()> action){auto b=new PixelButton(f,s,std::move(title),std::move(action));addChild(b);return b;};close_=button(U"",[this]{closeWindow(nullptr);});close_->iconSkin=&icons;close_->icon="close";close_->skinStyle="icon_button";done_=button(U"关闭",[this]{if(confirm_){confirm_=false;invalidate();}else closeWindow(nullptr);});exportButton_=button(U"导出 JSON",[this]{if(!confirm_&&export_)export_();});exportButton_->iconSkin=&icons;exportButton_->icon="export";exportButton_->iconWithCaption=true;resetButton_=button(U"重置",[this]{if(confirm_){if(reset_)reset_();confirm_=false;}else confirm_=true;invalidate();});resetButton_->iconSkin=&icons;resetButton_->icon="restore";resetButton_->iconWithCaption=true;
 }
 void setError(std::u32string e){error_=std::move(e);invalidate();}
 void update(usage::Summary value){summary_=std::move(value);invalidate();}
 gfx::Size minimumDialogSize(int)const override{return {460*uiScale,400*uiScale};}
 void onResize(ui::ResizeEvent& ev)override{setBoundsQuietly(ev.bounds());const auto r=bounds();const int w=r.w/uiScale,h=r.h/uiScale;auto place=[&](ui::Widget* c,gfx::Rect b){c->setBounds(uiPhysical(b).offset(r.origin()));};layoutHeaderButton(close_);place(exportButton_,{6,DialogLayout::footer(h),100,textControlHeight});place(resetButton_,{112,DialogLayout::footer(h),60,textControlHeight});place(done_,{w-61,DialogLayout::footer(h),55,textControlHeight});}
 void paintDialogContents(ui::PaintEvent& ev)override{auto& g=*ev.graphics();UiPaintScale scale(g);const auto r=uiLogical(clientBounds());drawDialogTitle(font_,g,r,confirm_?U"重置使用统计":U"使用统计");if(confirm_){font_.draw(g,U"确定重置全部使用统计吗？",8,65,skin_["text"]);font_.draw(g,U"此操作无法撤销。点击重置确认，关闭取消。",8,85,skin_["muted"]);return;}const auto& s=summary_;const auto& d=s.data;font_.draw(g,d.enabled?U"使用统计已开启":U"使用统计已关闭",8,DialogLayout::bodyTop,skin_["text"]);font_.draw(g,U"数据只保存在本机，不记录工程名称、文件路径或创作内容。",8,DialogLayout::bodyTop+14,skin_["muted"]);const std::vector<std::pair<std::u32string,std::u32string>> cards{{U"绘画时长",duration(d.drawingTimeMs)},{U"总使用时长",duration(d.totalUsageMs)},{U"启动次数",unicodeText(std::to_string(d.launchCount))},{U"连续使用天数",unicodeText(std::to_string(s.consecutiveUsageDays))},{U"累计使用天数",unicodeText(std::to_string(s.totalUsageDays))},{U"平均会话",duration(s.averageSessionMs)},{U"新建工程",unicodeText(std::to_string(d.newProjectCount))},{U"保存次数",unicodeText(std::to_string(d.saveCount))},{U"绘画笔画",unicodeText(std::to_string(d.drawingStrokeCount))},{U"最长会话",duration(d.longestSessionMs)},{U"最近 7 天",duration(s.last7DaysMs)},{U"最近 30 天",duration(s.last30DaysMs)}};const int cw=(r.w-20)/3;for(int i=0;i<int(cards.size());++i){const int x=8+(i%3)*(cw+2),y=DialogLayout::bodyTop+34+(i/3)*33;g.fillRect(skin_["panel"],{x,y,cw,30});font_.draw(g,cards[i].first,x+3,y+3,skin_["muted"]);font_.draw(g,cards[i].second,x+3,y+16,skin_["text"]);}chart(g,s.dailyTrend,DialogLayout::bodyTop+170,r.w,false);chart(g,s.weeklyTrend,DialogLayout::bodyTop+242,r.w,true);if(!error_.empty())font_.draw(g,error_,8,DialogLayout::footer(r.h)-13,skin_["text"]);}
 bool onProcessMessage(ui::Message* msg)override{if(processDialogGeometry(msg))return true;if(msg->type()==ui::kMouseMoveMessage){const auto p=uiLocalPoint(static_cast<ui::MouseMessage*>(msg)->position(),bounds().origin());const int y=p.y-DialogLayout::bodyTop;const bool weekly=y>=242;const int start=weekly?242:170;if(y>=start&&y<start+66){auto& active=weekly?activeWeekly_:activeDaily_;const int n=weekly?12:30;active=std::clamp((p.x-8)/std::max(1,(bounds().w/uiScale-16)/n),0,n-1);invalidate();}}if(msg->type()==ui::kKeyDownMessage){const auto k=static_cast<ui::KeyMessage*>(msg)->scancode();if(k==ui::kKeyEsc){if(confirm_){confirm_=false;invalidate();}else closeWindow(nullptr);return true;}if(k==ui::kKeyLeft||k==ui::kKeyRight){activeDaily_=std::clamp(activeDaily_+(k==ui::kKeyLeft?-1:1),0,29);activeWeekly_=std::clamp(activeWeekly_+(k==ui::kKeyLeft?-1:1),0,11);invalidate();return true;}}return PixelPopupWindow::onProcessMessage(msg);}
};
