void Editor::initializeUsageStatistics(bool testing){usageStatisticsEphemeral_=testing;std::string source;if(!testing)try{const auto path=palettePreferencePath().parent_path()/"usage-statistics.json";if(std::filesystem::exists(path)){if(std::filesystem::file_size(path)>4*1024*1024)throw std::runtime_error("Usage statistics too large");std::ifstream in(path,std::ios::binary);source.assign(std::istreambuf_iterator<char>(in),{});if(in.bad())throw std::runtime_error("Usage statistics read");}}catch(const std::exception& e){usageStatisticsEphemeral_=true;status_=U"使用统计读取失败："+unicodeText(e.what());}usageStatistics_.initialize(source);runtimePreferences_.set("general.preferences.usageStatisticsEnabled",usageStatistics_.data().enabled?"true":"false");menuCommands_.bind("usageStatistics",{[this]{showUsageStatistics();},[this]{return pending_==Pending::None;},{}});persistUsageStatistics();}
void Editor::persistUsageStatistics(){if(usageStatisticsEphemeral_||!usageStatistics_.initialized()||!usageStatistics_.dirty())return;try{const auto path=palettePreferencePath().parent_path()/"usage-statistics.json";std::filesystem::create_directories(path.parent_path());const auto json=usage::encode(usageStatistics_.data());writeExportBytesAtomic(path,std::vector<std::uint8_t>(json.begin(),json.end()));usageStatistics_.persisted();}catch(const std::exception& e){usageStatisticsEphemeral_=true;status_=U"使用统计保存失败："+unicodeText(e.what());}}
void Editor::usageStatisticsTick(){if(usageStatistics_.initialized()&&usageStatistics_.tick())persistUsageStatistics();}
void Editor::setUsageStatisticsEnabled(bool enabled){usageStatistics_.setEnabled(enabled);runtimePreferences_.set("general.preferences.usageStatisticsEnabled",enabled?"true":"false");persistUsageStatistics();}
void Editor::showUsageStatistics(bool verify){if(pending_!=Pending::None)return;UsageDialog* active=nullptr;UsageDialog popup(font_,skin_,toolIcons_,usageStatistics_.snapshot(),[this,&active]{wchar_t filename[32768]=L"usage-statistics.json";OPENFILENAMEW d{};d.lStructSize=sizeof(d);d.hwndOwner=GetActiveWindow();d.lpstrFile=filename;d.nMaxFile=32768;d.lpstrFilter=L"JSON\0*.json\0\0";d.lpstrDefExt=L"json";d.Flags=OFN_EXPLORER|OFN_NOCHANGEDIR|OFN_PATHMUSTEXIST|OFN_OVERWRITEPROMPT;if(!GetSaveFileNameW(&d))return;try{const auto json=usage::encode(usageStatistics_.snapshot().data);writeExportBytesAtomic(filename,std::vector<std::uint8_t>(json.begin(),json.end()));}catch(const std::exception& e){status_=U"统计导出失败："+unicodeText(e.what());if(active)active->setError(status_);}},[this,&active]{usageStatistics_.reset();persistUsageStatistics();if(active)active->update(usageStatistics_.snapshot());});active=&popup;popup.setDisplay(display(),false);const auto r=bounds();popup.setBounds({r.center().x-250*uiScale,r.center().y-210*uiScale,500*uiScale,420*uiScale});ui::Timer live(1000,&popup);live.Tick.connect([&]{popup.update(usageStatistics_.snapshot());});live.start();ui::Timer timer(150,&popup);if(verify){timer.Tick.connect([&]{timer.stop();writeSmokeFrame(popup.display()->nativeSurface().get(),assets_.parent_path()/"usage-statistics-smoke.bmp");popup.closeWindow(nullptr);});timer.start();}popup.openWindowInForeground();live.stop();timer.stop();requestFocus();refresh();}
void Editor::smokeUsageStatistics(){smoke_=true;if(!usageStatisticsEphemeral_||!menuCommands_.connected("usageStatistics"))throw std::runtime_error("Usage menu/isolation");setUsageStatisticsEnabled(false);const auto count=usageStatistics_.data().saveCount;usageStatistics_.recordEvent("save");if(usageStatistics_.data().saveCount!=count)throw std::runtime_error("Usage disabled event");setUsageStatisticsEnabled(true);usageStatistics_.recordEvent("save");if(usageStatistics_.data().saveCount!=count+1)throw std::runtime_error("Usage enabled event");const auto json=usage::encode(usageStatistics_.snapshot().data);const auto path=assets_.parent_path()/"usage-statistics-test-owned.json";writeExportBytesAtomic(path,std::vector<std::uint8_t>(json.begin(),json.end()));std::ifstream in(path,std::ios::binary);const std::string saved((std::istreambuf_iterator<char>(in)),{});if(usage::parse(saved).saveCount!=count+1)throw std::runtime_error("Usage disk roundtrip");usageStatistics_.reset();document=Document(8,8);documentOpen_=true;homeOpen_=false;selectionTool_=shapeTool_=gradientTool_=fillTool_=handTool_=eraser_=navigation_.zoomTool_=eyedropperTool_=false;ink_=0xff123456;fitCanvas();refresh();requestFocus();const auto point=canvasViewport().center();const auto strokes=usageStatistics_.data().drawingStrokeCount;for(auto type:{ui::kMouseDownMessage,ui::kMouseUpMessage}){ui::MouseMessage mouse(type,os::PointerType::Mouse,ui::kButtonLeft,ui::kKeyNoneModifier,point);mouse.setDisplay(display());onProcessMessage(&mouse);}if(usageStatistics_.data().drawingStrokeCount!=strokes+1||!document.canUndo())throw std::runtime_error("Usage actual committed brush collection");const auto time=usageStatistics_.data().drawingTimeMs;if(!time)throw std::runtime_error("Usage committed brush duration");document.undo();if(usageStatistics_.data().drawingStrokeCount!=strokes+1)throw std::runtime_error("Usage undo changed cumulative activity");showUsageStatistics(true);}
